import type { MetadataRoute } from "next";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: "*",
      allow: "/",
      disallow: [
        "/api/",
        "/admin",
        "/billing",
        "/compose",
        "/contacts",
        "/history",
        "/settings",
        "/templates",
        "/usage",
      ],
    },
    sitemap: "https://www.mailloop.in/sitemap.xml",
  };
}
